/**
 * JobStatus
 *
 * Job status enumeration - Complete state machine.
 *
 * The workflow has 8 main stages with up to 3 human interaction points:
 * 1. Input & Setup (may include audio source selection)
 * 1b. Optional Audio Editing (BLOCKING) - trim/cut/mute/join input audio
 * 2. Parallel Processing (audio + lyrics)
 * 3. Title/End Screen Generation + Backing Vocals Analysis
 * 4. Countdown Padding Synchronization
 * 5. Combined Human Review (BLOCKING) - lyrics review + instrumental selection
 * 6. Video Finalization
 * 7. Distribution
 *
 * Note: As of 2026-01, lyrics review and instrumental selection are combined
 * into a single human review step. The user selects their instrumental
 * during the lyrics review phase, before the video is rendered.
 */
export type JobStatus = 'pending' | 'searching_audio' | 'awaiting_audio_selection' | 'downloading_audio' | 'download_pending_retry' | 'downloading' | 'awaiting_audio_edit' | 'in_audio_edit' | 'audio_edit_complete' | 'awaiting_duration_confirm' | 'separating_stage1' | 'separating_stage2' | 'audio_complete' | 'transcribing' | 'correcting' | 'lyrics_complete' | 'generating_screens' | 'applying_padding' | 'awaiting_review' | 'in_review' | 'review_complete' | 'rendering_video' | 'render_pending_capacity' | 'awaiting_instrumental_selection' | 'instrumental_selected' | 'generating_video' | 'encoding' | 'packaging' | 'uploading' | 'notifying' | 'complete' | 'prep_complete' | 'failed' | 'cancelled' | 'queued' | 'processing' | 'ready_for_finalization' | 'finalizing' | 'error';

